use std::path::{Path, PathBuf};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use tokio::fs;

// Payment receipt storage system
const RECEIPTS_DIR: &str = "/var/payments/receipts";
const TEMPLATES_DIR: &str = "/var/payments/templates";

#[derive(Clone, Debug)]
pub struct PaymentRecord {
    pub transaction_id: String,
    pub merchant_id: String,
    pub amount_cents: u64,
    pub currency: String,
    pub status: String,
}

#[derive(Clone)]
pub struct PaymentService {
    records: Arc<RwLock<HashMap<String, PaymentRecord>>>,
    path_cache: Arc<RwLock<HashMap<String, PathBuf>>>,
}

impl PaymentService {
    pub fn new() -> Self {
        Self {
            records: Arc::new(RwLock::new(HashMap::new())),
            path_cache: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    /// Validates that a component doesn't contain path separators
    fn validate_path_component(component: &str) -> bool {
        !component.contains('/') && !component.contains('\\')
            && component != ".." && component != "."
            && !component.is_empty()
    }

    /// Resolves a merchant's receipt directory, with caching
    async fn resolve_merchant_dir(&self, merchant_id: &str) -> Result<PathBuf, String> {
        // Check cache first
        {
            let cache = self.path_cache.read().await;
            if let Some(cached) = cache.get(merchant_id) {
                return Ok(cached.clone());
            }
        }

        if !Self::validate_path_component(merchant_id) {
            return Err("Invalid merchant ID".to_string());
        }

        let base = PathBuf::from(RECEIPTS_DIR);
        let merchant_dir = base.join(merchant_id);

        // Cache the resolved path
        {
            let mut cache = self.path_cache.write().await;
            cache.insert(merchant_id.to_string(), merchant_dir.clone());
        }

        Ok(merchant_dir)
    }

    /// Normalize a filename by resolving any URL-encoded sequences
    /// This handles cases where filenames come from HTTP request paths
    fn normalize_filename(raw: &str) -> String {
        let mut result = String::new();
        let bytes = raw.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'%' && i + 2 < bytes.len() {
                if let (Some(h), Some(l)) = (
                    (bytes[i+1] as char).to_digit(16),
                    (bytes[i+2] as char).to_digit(16),
                ) {
                    let decoded = (h * 16 + l) as u8 as char;
                    result.push(decoded);
                    i += 3;
                    continue;
                }
            }
            result.push(bytes[i] as char);
            i += 1;
        }
        result
    }

    /// Fetch a receipt file for a given transaction
    pub async fn get_receipt(
        &self,
        merchant_id: &str,
        transaction_id: &str,
    ) -> Result<Vec<u8>, String> {
        let merchant_dir = self.resolve_merchant_dir(merchant_id).await?;

        // Normalize the transaction ID (may come URL-encoded from HTTP layer)
        let normalized_txn = Self::normalize_filename(transaction_id);

        // Validate the normalized transaction ID contains no traversal
        if !Self::validate_path_component(&normalized_txn) {
            return Err("Invalid transaction ID".to_string());
        }

        let filename = format!("{}.pdf", normalized_txn);

        // Security check: ensure no path traversal in the final filename
        let final_path = merchant_dir.join(&filename);

        // Verify the resolved path is under the merchant directory
        // by canonicalizing and checking prefix relationship
        let canonical_base = fs::canonicalize(&merchant_dir)
            .await
            .map_err(|e| format!("Cannot resolve base: {}", e))?;
        let canonical_path = fs::canonicalize(&final_path)
            .await
            .map_err(|e| format!("Cannot resolve path: {}", e))?;

        if !canonical_path.starts_with(&canonical_base) {
            return Err("Path traversal detected".to_string());
        }

        fs::read(&canonical_path)
            .await
            .map_err(|e| format!("Failed to read receipt: {}", e))
    }

    /// Store a payment and generate receipt path
    pub async fn process_payment(
        &self,
        merchant_id: &str,
        transaction_id: &str,
        amount_cents: u64,
        currency: &str,
    ) -> Result<String, String> {
        if !Self::validate_path_component(merchant_id) {
            return Err("Invalid merchant ID".to_string());
        }

        let record = PaymentRecord {
            transaction_id: transaction_id.to_string(),
            merchant_id: merchant_id.to_string(),
            amount_cents,
            currency: currency.to_string(),
            status: "completed".to_string(),
        };

        {
            let mut records = self.records.write().await;
            records.insert(transaction_id.to_string(), record);
        }

        Ok(format!("Payment {} processed successfully", transaction_id))
    }

    /// Get a template file for receipt generation
    pub async fn get_template(&self, template_name: &str) -> Result<Vec<u8>, String> {
        if !Self::validate_path_component(template_name) {
            return Err("Invalid template name".to_string());
        }

        let template_path = PathBuf::from(TEMPLATES_DIR).join(template_name);
        fs::read(&template_path)
            .await
            .map_err(|e| format!("Failed to read template: {}", e))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_valid_receipt_path() {
        let svc = PaymentService::new();
        // This would fail on I/O but validates path logic
        let result = svc.get_receipt("merchant123", "txn_abc").await;
        assert!(result.is_err()); // File doesn't exist in test
    }

    #[tokio::test]
    async fn test_rejects_traversal_in_merchant() {
        let svc = PaymentService::new();
        let result = svc.get_receipt("..", "txn_abc").await;
        assert_eq!(result.unwrap_err(), "Invalid merchant ID");
    }
}
